export async function logPageView(page: string) {
  // Replace with your real analytics endpoint
  const endpoint = process.env.ANALYTICS_ENDPOINT ?? 'https://analytics.example.com/collect';

  try {
    await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        event: 'page_view',
        page,
        timestamp: Date.now(),
      }),
    });
  } catch (error) {
    console.error('Failed to log page view:', error);
  }
}

